def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    op = [h[1] for h in history]
    my = [h[0] for h in history]
    opD = op.count('D')
    opC = n - opD
    if opC == 0 and n >= 3:
        return 'D'
    last_op = op[-1]
    if last_op == 'C':
        return 'C'
    dd_streak = 0
    i = n - 1
    while i >= 0 and my[i] == 'D' and op[i] == 'D':
        dd_streak += 1
        i -= 1
    if dd_streak >= 2:
        lookback = min(n, 10)
        recent_opC = 0
        for j in range(n - lookback, n):
            if op[j] == 'C':
                recent_opC += 1
        if recent_opC > 0:
            return 'C'
        if dd_streak >= 5 and n % 10 == 0:
            return 'C'
    return 'D'
